/* request: resolve the SID cookie, then look the record up */
char sid[33];
if (!cookie_get(req, "SID", sid, sizeof sid)) session_id_new(sid);
lock(&store.mu);
session_t *s = store_get(&store, sid);
if (!s) s = store_put(&store, sid, session_new());
lock_release(&store.mu);
response_set_cookie(res, "SID", sid);   /* HttpOnly; Secure; SameSite=Lax */
/* store_get returns NULL for an expired record: session_new() restarts the talk */
